function setLanguage(lang){
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
  while(walker.nextNode()){
    const node=walker.currentNode;
    if(node.parentElement?.closest('script,style'))continue;
    if(!originalText.has(node))originalText.set(node,node.nodeValue);
    const source=originalText.get(node),key=source.trim();
    node.nodeValue=lang==='kk'&&kk[key]?source.replace(key,kk[key]):source;
  }
  document.documentElement.lang=lang;
  document.title=metaCopy[lang].title;
  document.querySelector('meta[name="description"]')?.setAttribute('content',metaCopy[lang].description);
  document.querySelector('meta[property="og:title"]')?.setAttribute('content',metaCopy[lang].title);
  document.querySelector('meta[property="og:description"]')?.setAttribute('content',metaCopy[lang].description);
  const waTexts=lang==='kk'
    ?['Сәлеметсіз бе! Болат құбырлардың бар-жоғын білгім келеді','Сәлеметсіз бе! Болат құбырлар бойынша кеңес қажет']
    :['Здравствуйте! Хочу уточнить наличие стальных труб','Здравствуйте! Нужна консультация по стальным трубам'];
  document.querySelectorAll('a[href*="wa.me"]').forEach((link,index)=>link.href=`https://wa.me/77759331301?text=${encodeURIComponent(waTexts[index]||waTexts[0])}`);
  const menu=document.querySelector('.menu');
  if(menu)menu.setAttribute('aria-label',lang==='kk'?'Мәзірді ашу':'Открыть меню');
  const heroSearch=document.querySelector('#hero-search');
  if(heroSearch)heroSearch.placeholder=lang==='kk'?'Мысалы: 530×8 құбыры немесе қоршауға арналған':'Например: труба 530×8 или для забора';
  document.querySelectorAll('[data-lang]').forEach(button=>button.classList.toggle('active',button.dataset.lang===lang));
  document.querySelector('.lang-switch')?.setAttribute('aria-label',lang==='kk'?'Тілді таңдау':'Выбор языка');
  localStorage.setItem('truebusiness-language',lang);
  dispatchEvent(new CustomEvent('languagechange',{detail:{lang}}));
}

document.querySelectorAll('[data-lang]').forEach(button=>button.addEventListener('click',()=>setLanguage(button.dataset.lang)));
setLanguage(localStorage.getItem('truebusiness-language')==='kk'?'kk':'ru');
